  interactive={true}
  chartHeaderConfig={{ chartTitleValue: "Badge shows data VALUE" }}
  barGroupConfig={{
    hoverType: "individual",
    hoverBadge: true,
  }}
/>
```

### Group Mode - Shows Category Label

```tsx
